using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Enums;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Billing;[Authorize(Policy="PlatformFinanceOrHigher")]public sealed class IndexModel(OrcaFacilDbContext db):PageModel{public decimal Mrr{get;private set;}public int ActiveSubscriptions{get;private set;}public int OverdueInvoices{get;private set;}public decimal OverdueAmount{get;private set;}public async Task OnGetAsync(CancellationToken ct){var active=db.AccountModuleSubscriptions.Where(x=>!x.IsDeleted&&x.Status==SaasModuleSubscriptionStatus.Active);ActiveSubscriptions=await active.CountAsync(ct);Mrr=await active.SumAsync(x=>(decimal?)(x.BillingPeriod==SaasBillingPeriod.Annual?x.ContractedPrice/12:x.ContractedPrice-x.DiscountAmount),ct)??0;var overdue=db.BillingInvoices.Where(x=>!x.IsDeleted&&x.Status==BillingInvoiceStatus.Overdue);OverdueInvoices=await overdue.CountAsync(ct);OverdueAmount=await overdue.SumAsync(x=>(decimal?)(x.Amount-x.PaidAmount),ct)??0;}}
